import { type ParentComponent } from "solid-js";

import { Activatable, ActivatableProps } from "#core/ui-next/components/activatable.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { IsControllerActive, IsTouchActive } from "#core/ui-next/services/input.js";

const CloseButtonComponent: ParentComponent<ActivatableProps> = (props) => {
	return (
		<Activatable
			{...props}
			audio={{
				...props.audio,
				onPress: props.audio?.onPress ?? "data-audio-primary-button-press",
				onFocus: props.audio?.onFocus ?? "data-audio-primary-button-focus",
			}}
			class={`${IsTouchActive() ? "size-16" : "size-12"} cursor-pointer group ${props.class ?? "relative"}`}
			classList={{
				hidden: IsControllerActive(),
			}}
			disableFocus={IsControllerActive()}
			hotkeyAction="cancel"
			navTrayText={props.navTrayText ?? "LOC_GENERIC_BACK"}
			name="CloseButton"
		>
			<div class="close-button__bg absolute inset-0" />
			<div class="close-button__bg-hover absolute inset-0 opacity-0 group-hover\:opacity-100 group-focus\:opacity-100 transition-opacity" />
			<div class="close-button__bg-pressed absolute inset-0 opacity-0 group-active\:opacity-100 group-pressed\:opacity-100" />
		</Activatable>
	);
};

/**
 * The close button for windows and popups.
 * Example:
 * ```tsx
 * <CloseButton onActivate={() => console.log("activated!")}/>
 * ```
 */
export const CloseButton = ComponentRegistry.register({
	name: "CloseButton",
	createInstance: CloseButtonComponent,
	images: ["blp:hud_closebutton", "blp:hud_closebutton_hover", "blp:hud_closebutton_pressed"],
});
